import {escape as esc,dayStrip,receipts,phone,when} from './day-ui.js';
import {morningAnswer} from './consistency-ui.js';
let priorFlag=null,changes=[];
export function enrichToday(w,{openPlan,publishSuggested,preview,state}){
  const panel=document.querySelector('#panel'),brief=w.morningBrief,summary=w.outdoorSummary;
  const changeLabel=!summary.available?'Verify conditions first':w.planning.flag==='green'&&summary.before===0?'No change needed':summary.before+' → '+summary.after+' min';
  if(priorFlag&&priorFlag!==w.planning.flag){changes.unshift({from:priorFlag,to:w.planning.flag,time:Date.now()});}
  priorFlag=w.planning.flag;
  const html=`${changes.length?`<section class="card flag-change"><h2>The air flag changed</h2><p>${esc(changes[0].from)} → ${esc(changes[0].to)} at ${when(changes[0].time/1000)}. Review the draft plan.</p><button data-draft>Review the draft plan</button><details><summary>Flag changes this session</summary>${changes.map(c=>`<p>${esc(c.from)} → ${esc(c.to)} · ${when(c.time/1000)}</p>`).join('')}</details></section>`:''}<div class="grid"><section class="card"><h2>Morning brief</h2><p class="muted">Tomorrow’s forecast</p><span class="badge ${esc(brief.flag)}">${esc(brief.flag)}</span><h3>Move PE and assembly indoors?</h3><p><strong>${esc(morningAnswer(brief))}</strong></p><p>${esc(brief.label)} · PM2.5 ${Number.isFinite(brief.pm25)?brief.pm25.toFixed(1):'Unavailable'} µg/m³</p>${brief.available?`<p>Valid ${when(brief.validAt,{scheduled:true})} · ${esc(brief.source)} · Retrieved ${when(brief.retrievedAt)}</p>`:''}<details><summary>Why this suggestion?</summary><p>${esc(brief.headline)}</p><p>${esc(brief.reason)}</p></details>${w.membership.role==='admin'?'<button data-morning-draft>Draft the morning message</button>':''}</section><section class="card"><h2>What changes in the school day</h2><p>Planned outdoors at orange or red</p><strong class="receipt-count">${esc(changeLabel)}</strong><p>If the suggested PE and assembly changes are reviewed and followed. ${summary.moved} minutes considered for an indoor alternative.</p><p class="muted">${esc(summary.label)} ${esc(summary.basis)}</p><details><summary>See each block</summary>${dayStrip(summary.blocks)}</details></section></div><section class="card"><h2>Data health</h2><p><b>${esc(w.dataHealth.status)}</b> · ${w.dataHealth.ageMinutes===null?'Observation time unavailable':w.dataHealth.ageMinutes+' minutes since observation'}</p><p>${esc(w.air.source)}<br>Observed ${when(w.air.observedAt)}<br>Last successful retrieval ${when(w.lastSuccessfulIngestion)}</p><p>Getting old after ${w.dataHealth.freshSeconds/3600} hour; stale after ${w.dataHealth.staleSeconds/3600} hours. Unknown conditions block publication.</p>${['Stale','Unavailable'].includes(w.dataHealth.status)?'<p class="notice">This reading is old or unavailable. Check the source before publishing.</p>':''}</section>`;
  (panel.querySelector('.decision-layout')||panel.querySelector('.hero')).insertAdjacentHTML('afterend',html);
  if(w.membership.role==='admin'){const hero=panel.querySelector('.hero');hero.insertAdjacentHTML('beforeend',`<p class="publication-status"><strong>${state.stage==='draft'?'Draft':state.stage==='reviewed'?'Reviewed':'Published'}</strong>${state.notice?` · ${esc(when(state.notice.time,{schoolEvent:true}))}`:' · Not yet shared'}</p><div class="row decision-actions"><button data-publish-suggested ${state.notice?'hidden disabled':w.planning.flag==='unknown'?'disabled':''}>Publish plan</button><button class="secondary" data-edit-wording>${state.notice?'Draft a revision':'Edit wording'}</button></div><div class="decision-impact"><span>What changes · outdoor minutes at orange/red</span><strong>${esc(changeLabel)}</strong><small>Planning estimate if the suggested changes are reviewed and followed.</small></div>`);hero.querySelector('[data-publish-suggested]').onclick=publishSuggested;hero.querySelector('[data-edit-wording]').onclick=()=>openPlan(w.planning.actions[0].text);}
  panel.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>openPlan(w.planning.actions[0].text));
  panel.querySelectorAll('[data-morning-draft]').forEach(b=>b.onclick=()=>openPlan(brief.headline));
  const sourceCard=[...panel.querySelectorAll('section.card')].find(card=>card.querySelector('h2')?.textContent==='Data sources');
  if(sourceCard){sourceCard.querySelector('h2').textContent='Sources';sourceCard.insertAdjacentHTML('beforeend',`<details><summary>Public-source registry</summary>${[['CPCB National Air Quality Index','CPCB'],['OpenAQ','OpenAQ'],['NASA FIRMS',null],['India Meteorological Department',null],['data.gov.in','CPCB'],['Registry of Open Data on AWS',null]].map(([label,key])=>`<p><b>${esc(label)}</b> · ${key&&w.air.mode!=='demo'&&w.air.source.includes(key)?'Used now':'Not used'}${key?' · adapter available':''}</p>`).join('')}<p>Current input: ${esc(w.air.source)}. Freshness: ${esc(w.dataHealth.status)}. Automatic preview uses fixtures. Demo tools can request a live regional model; no external messages are sent.</p></details>`);}
}
export function checklist(w,submit){
  const panel=document.querySelector('#panel');
  const tasks=(w.checklist||[]).filter(t=>t.role===w.membership.role);
  if(!tasks.length)return;
  panel.insertAdjacentHTML('beforeend',`<section class="card"><h2>Your plan checklist</h2>${tasks.map(t=>{const done=w.completions.some(c=>c.taskId===t.id);return `<p>${esc(t.text)}</p><button class="secondary" data-task="${esc(t.id)}" ${done?'disabled':''}>${done?'Completion recorded':'Confirm reviewed and completed'}</button>`;}).join('')}<p class="muted">Only confirm what you actually completed. Receipts record review and completion, not health outcomes.</p></section>`);
  panel.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>submit(b.dataset.task));
}
export async function operations(w,fetchData,openPlan){
  const panel=document.querySelector('#panel'),result=await fetchData();
  if(!panel.isConnected)return;
  const plans=result.plans,week=plans.filter(p=>p.time>Date.now()/1000-7*86400);
  panel.innerHTML=`<section class="card"><h2>Plan history</h2><p>${w.air.mode==='demo'?'Demo data. ':''}Published instructions and explicit reviews.</p>${plans.map((p,i)=>`<details><summary>${when(p.time,{schoolEvent:true})} · ${esc(p.flag)} · ${p.receiptSummary.confirmed} of ${p.receiptSummary.total} reviewed</summary><p>${p.reasons.map(esc).join(' ')}</p><p>Author role: ${esc(p.authorRole||'admin')}</p><button class="secondary" data-reuse="${i}">Reuse this wording</button></details>`).join('')||'<p>No published plans yet. Open School plan to draft one.</p>'}<button data-new-draft>Open School plan</button></section><section class="card"><h2>This week’s review summary</h2><p>Days classified by the highest available sample; missing days unknown.</p><div class="weekly-flags">${Object.entries(result.weekly.daysByFlag).map(([flag,n])=>`<span class="badge ${esc(flag)}">${esc(flag)} · ${n} days</span>`).join(' ')}</div><p>${week.length} plans published · ${week.reduce((n,p)=>n+p.receiptSummary.confirmed,0)} adult confirmations</p><p>These are operational reviews, not exposure or health outcomes. Median time to review: ${result.weekly.medianSecondsToReview===null?'Unavailable':Math.round(result.weekly.medianSecondsToReview/60)+' min'}. Confirmed share: ${result.weekly.confirmedShare===null?'Unavailable':Math.round(result.weekly.confirmedShare*100)+'%'}.</p></section><section class="card"><h2>Activity log</h2>${result.log.map(l=>`<p>${when(l.time)} · ${esc(l.role)} · ${esc(l.action)}</p>`).join('')||'<p>No recorded changes yet. Publish a plan to begin the review trail.</p>'}</section>`;
  panel.querySelectorAll('[data-reuse]').forEach(b=>b.onclick=()=>openPlan(plans[Number(b.dataset.reuse)].reasons.join(' ')));
  panel.querySelector('[data-new-draft]').onclick=()=>openPlan('');
}
export function classes(w){
  const panel=document.querySelector('#panel'),notice=w.notice;
  const classes=w.membership.role==='teacher'?w.classes.filter(c=>c.id===w.membership.class_id):w.classes;
  const confirmedCount=classes.filter(c=>notice&&w.receipts.some(r=>r.class_id===c.id&&r.kind==='acknowledge')).length;
  panel.innerHTML=`<section class="card"><h2>Class plans</h2><p><strong>${confirmedCount} of ${classes.length} classes confirmed</strong></p><p>The shared school timetable applies to these classes; class-specific rooms must be reviewed by the teacher.</p>${classes.map(c=>{const confirmed=w.receipts.some(r=>r.class_id===c.id&&r.kind==='acknowledge');return `<details><summary>${esc(c.label)} · ${!notice?'Not sent':confirmed?'Read and checked by teacher':'Sent; awaiting class check'}</summary>${dayStrip(w.dayPlan.timetable)}<p>Room: ${esc(c.room_id||'Not assigned')} · Orange/red outdoor-time planning estimate: ${w.outdoorSummary.available?w.outdoorSummary.before+' → '+w.outdoorSummary.after+' minutes':'Unavailable until conditions are verified'}.</p><p>Planning estimate. Not an exposure or health measurement.</p></details>`;}).join('')||'<p>No classes linked. Ask the school administrator to add your class.</p>'}</section>`;
}
export function notificationExtras(w,{post,refresh,preview,fetchOperations,notify}){
  const panel=document.querySelector('#panel'),usage=w.notificationUsage;
  panel.insertAdjacentHTML('beforeend',`<section class="card"><h2>Notification limits</h2>${Object.entries(usage.channels).map(([channel,count])=>`<p>${esc(channel)}: ${count} of ${w.preferences.dailyCap} messages used today</p>`).join('')}<p>Quiet hours ${esc(w.preferences.quietStart)}–${esc(w.preferences.quietEnd)} · ${usage.quietNow?'Active now':'Not active now'} · ${esc(w.school.timezone)}</p>${preview?'<p class="muted">Notification limits use the actual school-local clock. Demo display timestamps are shifted to a 07:30 morning.</p>':''}<div class="row">${w.membership.role==='admin'?'<button id="remind-unread">Remind people who have not confirmed</button>':''}<button class="secondary" id="test-to-me">Send a test to me</button></div><div id="limit-feedback" role="status"></div><p>${preview?'Demo data. Only in-app records are generated. No external messages are sent.':'Each recipient’s preferences are checked again before dispatch.'}</p></section>`);
  const blocked=usage.quietNow||Object.values(usage.channels).some(n=>n>=w.preferences.dailyCap)||!w.notice;
  panel.querySelectorAll('#remind-unread,#test-to-me').forEach(b=>{b.disabled=blocked;b.title=blocked?'Publish a plan, wait for quiet hours to end, and keep within the daily cap.':'';b.onclick=async()=>{try{const result=await post(b.id==='remind-unread'?'remind':'test-notification',{requestId:crypto.randomUUID()});await refresh();notify(result.note);}catch(e){document.querySelector('#limit-feedback').textContent=e.message;}};});
  const remind=panel.querySelector('#remind-unread');if(remind&&w.reminderState){remind.disabled=!w.reminderState.allowed;remind.title=w.reminderState.reason;remind.insertAdjacentHTML('afterend',`<p class="muted">${esc(w.reminderState.reason)}</p>`);}
  if(w.membership.role==='admin')void fetchOperations().then(result=>{if(!panel.isConnected)return;panel.insertAdjacentHTML('beforeend',`<section class="card"><h2>School send log</h2><div class="scroll"><table><thead><tr><th>Time</th><th>Audience</th><th>Channel</th><th>Language</th><th>Status</th></tr></thead><tbody>${result.deliveries.map(d=>`<tr><td>${when(d.createdAt)}</td><td>${esc(d.audienceRole)}</td><td>${esc(d.channel)}</td><td>${esc(d.language||'Not recorded')}</td><td>${esc(d.status)}</td></tr>`).join('')}</tbody></table></div><p>Delivery acceptance is not a review receipt. ${preview?'Demo data. No external sends.':''}</p></section>`);}).catch(e=>{if(panel.isConnected)document.querySelector('#limit-feedback').textContent=e.message;});
  const form=panel.querySelector('#prefs');
  const previewBox=document.createElement('div');previewBox.id='notification-phone';form.after(previewBox);
  const show=()=>previewBox.innerHTML=phone(w.notice?.reasons.join(' ')||w.planning.actions[0].text,w.notice?.flag||w.planning.flag,form.elements.language.value);
  form.elements.language.addEventListener('change',show);show();
}
